-- =====================================================================
-- FitPower - Tucson S.R.L.  |  init.sql (estructura + datos de prueba)
-- Datos generados al 09/11/2026 (fechas coherentes con ese dia)
--
-- USUARIOS (310 en total)
--   id 1          Administrador  admin01 / hash_admin_123
--   id 2-3        Entrenadores   entrenador01 / hash_juan_456 , entrenador02 / hash_lucia_789
--   id 4-8        Socios         martin01, ana01, carlos01, laura01, pedro01 (contrasenas originales)
--   id 9-12       Entrenadores de la landing:
--                   Ibai / hash_ibai_666         (Llanos, Musculacion)
--                   Joaquin / hash_joaquin_777   (Dominguez, Funcional)
--                   German / hash_german_888     (Garmendia, CrossFit)
--                   Darren / hash_darren_999     (Jason, Nutricion)
--   id 13-310     Socios generados  ->  contrasena = hash_<nombre_usuario>
--                   ej: usuario 'sofia02' -> contrasena 'hash_sofia02'
--
-- Socios: 303 (242 con membresia activa, 61 vencidas)
-- En PERSONA, id_persona coincide con id_usuario para todos los registros.
-- Planes alineados con la landing: Basico $1200, Pro $1500, Elite $2100 (mensuales).
-- =====================================================================

-- =====================================================================
-- ESTRUCTURA DE LA BASE
-- Este archivo solo se ejecuta cuando la base está vacía (primer arranque
-- de Docker). Para volver a cargarlo: docker compose down -v y up -d.
-- =====================================================================
--
-- utf8mb4: permite guardar tildes, ñ y emojis sin problemas.
SET NAMES utf8mb4;

-- Roles del sistema: 1 = Administrador, 2 = Entrenador, 3 = Socio.
CREATE TABLE TIPOUSUARIO (
    id_rol INT AUTO_INCREMENT PRIMARY KEY,
    nombre_rol VARCHAR(50) NOT NULL
);

-- Cuentas para iniciar sesión.
-- hash: contraseña con password_hash (las de prueba están en texto plano y
--       se convierten a hash la primera vez que el usuario inicia sesión).
-- activo: 0 = cuenta desactivada por el admin (no puede iniciar sesión).
CREATE TABLE USUARIO (
    id_usuario INT AUTO_INCREMENT PRIMARY KEY,
    id_rol INT NOT NULL,
    nombre_usuario VARCHAR(50) NOT NULL UNIQUE,
    email VARCHAR(100) NOT NULL UNIQUE,
    hash VARCHAR(150) NOT NULL,
    activo TINYINT(1) NOT NULL DEFAULT 1,
    FOREIGN KEY (id_rol) REFERENCES TIPOUSUARIO(id_rol)
);

-- Planes de membresía (Básico, Pro, Elite).
CREATE TABLE PLAN (
    id_plan INT AUTO_INCREMENT PRIMARY KEY,
    nombre VARCHAR(50) NOT NULL,
    precio FLOAT NOT NULL,
    duracion VARCHAR(50),
    descripcion TEXT
);

-- Datos personales de cada usuario (una persona por usuario).
-- Socio: plan y fechas de la membresía, y su entrenador (id_entrenador).
-- Entrenador: especialidad. Todos: perfil (nacimiento, altura, sobre mí, foto).
CREATE TABLE PERSONA (
    id_persona INT AUTO_INCREMENT PRIMARY KEY,
    id_usuario INT NOT NULL,
    id_plan INT,
    apellido VARCHAR(50),
    fecha_inicio DATE,
    fecha_fin DATE,
    especialidad VARCHAR(70),
    fecha_nacimiento DATE NULL,
    altura INT NULL,
    sobre_mi TEXT NULL,
    id_entrenador INT NULL,
    foto VARCHAR(100) NULL,
    FOREIGN KEY (id_usuario) REFERENCES USUARIO(id_usuario),
    FOREIGN KEY (id_plan) REFERENCES PLAN(id_plan),
    FOREIGN KEY (id_entrenador) REFERENCES PERSONA(id_persona)
);

-- Salas del gimnasio.
CREATE TABLE SALA (
    id_sala INT AUTO_INCREMENT PRIMARY KEY,
    nombre VARCHAR(50) NOT NULL
);

-- Rutinas de entrenamiento (nombre y descripción).
CREATE TABLE RUTINA (
    id_rutina INT AUTO_INCREMENT PRIMARY KEY,
    nombre VARCHAR(50) NOT NULL,
    descripcion TEXT
);

-- Quién creó cada rutina (un entrenador, o el propio socio).
-- Se usa para saber qué rutinas puede editar un socio.
CREATE TABLE CREA (
    id_rutina INT NOT NULL,
    id_persona INT NOT NULL,
    PRIMARY KEY (id_rutina, id_persona),
    FOREIGN KEY (id_rutina) REFERENCES RUTINA(id_rutina),
    FOREIGN KEY (id_persona) REFERENCES PERSONA(id_persona)
);

-- Ejercicios disponibles. activo = 0 significa desactivado (no se borra,
-- para no romper las rutinas que ya lo usan). La imagen se guarda como archivo
-- en front/dist/assets/Ejercicios/{id}.png|jpg|webp.
CREATE TABLE EJERCICIO (
    id_ejercicio INT AUTO_INCREMENT PRIMARY KEY,
    nombre VARCHAR(50) NOT NULL,
    descripcion TEXT,
    nivel VARCHAR(100),
    grupo_muscular VARCHAR(70),
    activo TINYINT(1) NOT NULL DEFAULT 1
);

-- Ejercicios de cada rutina con series, repeticiones, descanso (segundos) y orden.
CREATE TABLE DETALLERUTINA (
    id_rutina INT NOT NULL,
    id_ejercicio INT NOT NULL,
    series INT,
    repeticiones INT,
    descanso INT,
    observaciones TEXT,
    orden_ejercicios INT,
    PRIMARY KEY (id_rutina, id_ejercicio),
    FOREIGN KEY (id_rutina) REFERENCES RUTINA(id_rutina),
    FOREIGN KEY (id_ejercicio) REFERENCES EJERCICIO(id_ejercicio)
);

-- Mediciones del socio a lo largo del tiempo (peso, masa muscular, grasa, racha).
CREATE TABLE PROGRESO (
    id_progreso INT AUTO_INCREMENT PRIMARY KEY,
    id_persona INT NOT NULL,
    fecha DATE NOT NULL,
    peso FLOAT,
    racha_actual INT,
    masa_muscular FLOAT,
    grasa FLOAT,
    observaciones TEXT,
    FOREIGN KEY (id_persona) REFERENCES PERSONA(id_persona)
);

-- Objetivos personales del socio. porcentaje: progreso de 0 a 100.
CREATE TABLE OBJETIVO (
    id_objetivo INT AUTO_INCREMENT PRIMARY KEY,
    id_persona INT NOT NULL,
    titulo VARCHAR(50) NOT NULL,
    descripcion TEXT,
    estado VARCHAR(50),
    fecha_inicio DATE,
    fecha_fin DATE,
    porcentaje INT NOT NULL DEFAULT 0,
    FOREIGN KEY (id_persona) REFERENCES PERSONA(id_persona)
);

-- Logros que se pueden obtener.
CREATE TABLE LOGRO (
    id_logro INT AUTO_INCREMENT PRIMARY KEY,
    nombre VARCHAR(50) NOT NULL,
    descripcion TEXT,
    icono VARCHAR(100)
);

-- Logros que obtuvo cada socio y cuándo.
CREATE TABLE OBTIENE (
    id_persona INT NOT NULL,
    id_logro INT NOT NULL,
    fecha_obtenido DATE NOT NULL,
    PRIMARY KEY (id_persona, id_logro),
    FOREIGN KEY (id_persona) REFERENCES PERSONA(id_persona),
    FOREIGN KEY (id_logro) REFERENCES LOGRO(id_logro)
);

-- Compras de productos. estado: Pendiente (reservada) o Pagada (pagó en recepción).
CREATE TABLE COMPRA (
    id_compra INT AUTO_INCREMENT PRIMARY KEY,
    id_persona INT NOT NULL,
    fecha DATE NOT NULL,
    metodo_pago VARCHAR(50),
    estado VARCHAR(50),
    FOREIGN KEY (id_persona) REFERENCES PERSONA(id_persona)
);

-- Categorías de productos (Suplementos, Indumentaria, Accesorios).
CREATE TABLE CATEGORIA (
    id_categoria INT AUTO_INCREMENT PRIMARY KEY,
    nombre VARCHAR(50) NOT NULL
);

-- Productos de la tienda con precio y stock.
CREATE TABLE PRODUCTO (
    id_producto INT AUTO_INCREMENT PRIMARY KEY,
    id_categoria INT NOT NULL,
    nombre VARCHAR(50) NOT NULL,
    descripcion TEXT,
    precio FLOAT NOT NULL,
    stock INT NOT NULL,
    FOREIGN KEY (id_categoria) REFERENCES CATEGORIA(id_categoria)
);

-- Productos de cada compra. El precio se guarda en el momento de la compra
-- (precio_unitario), así un cambio de precio posterior no altera compras viejas.
-- Por esta tabla no se puede borrar un producto que ya se vendió.
CREATE TABLE DETALLECOMPRA (
    id_compra INT NOT NULL,
    id_producto INT NOT NULL,
    total FLOAT,
    precio_unitario FLOAT,
    cantidad INT,
    PRIMARY KEY (id_compra, id_producto),
    FOREIGN KEY (id_compra) REFERENCES COMPRA(id_compra),
    FOREIGN KEY (id_producto) REFERENCES PRODUCTO(id_producto)
);

-- Reseñas de productos. La clave (producto, persona) hace que cada persona
-- tenga una sola reseña por producto.
CREATE TABLE RESENA (
    id_producto INT NOT NULL,
    id_persona INT NOT NULL,
    fecha_publicacion DATE NOT NULL,
    puntuacion FLOAT,
    comentario TEXT,
    PRIMARY KEY (id_producto, id_persona),
    FOREIGN KEY (id_producto) REFERENCES PRODUCTO(id_producto),
    FOREIGN KEY (id_persona) REFERENCES PERSONA(id_persona)
);

-- Días que el socio fue al gimnasio (se usa para la racha y el calendario).
CREATE TABLE ASISTENCIA (
    id_asistencia INT AUTO_INCREMENT PRIMARY KEY,
    id_persona INT NOT NULL,
    fecha DATE NOT NULL,
    hora_entrada TIME,
    hora_salida TIME,
    FOREIGN KEY (id_persona) REFERENCES PERSONA(id_persona)
);

-- Entrenamientos terminados: qué rutina hizo el socio, cuándo y cuántos minutos.
CREATE TABLE ENTRENAMIENTO_REALIZADO (
    id_entrenamiento INT AUTO_INCREMENT PRIMARY KEY,
    id_persona INT NOT NULL,
    id_rutina INT NOT NULL,
    fecha DATETIME NOT NULL,
    duracion INT NOT NULL,
    FOREIGN KEY (id_persona) REFERENCES PERSONA(id_persona),
    FOREIGN KEY (id_rutina) REFERENCES RUTINA(id_rutina)
);

-- Mensajes para los usuarios (reservada para una función futura).
CREATE TABLE MENSAJE (
    id_mensaje INT AUTO_INCREMENT PRIMARY KEY,
    id_persona INT NOT NULL,
    contenido TEXT,
    fecha_envio DATETIME,
    leido BOOLEAN,
    FOREIGN KEY (id_persona) REFERENCES PERSONA(id_persona)
);

-- Qué rutinas tiene cada socio.
CREATE TABLE ASIGNA (
    id_rutina INT NOT NULL,
    id_persona INT NOT NULL,
    fecha_asignacion DATE,
    PRIMARY KEY (id_rutina, id_persona),
    FOREIGN KEY (id_rutina) REFERENCES RUTINA(id_rutina),
    FOREIGN KEY (id_persona) REFERENCES PERSONA(id_persona)
);


-- Qué socios atiende cada entrenador, con día y horario: es la agenda del entrenador.
CREATE TABLE SUPERVISA (
    id_entrenador INT NOT NULL,
    id_persona INT NOT NULL,
    dia_semana VARCHAR(20) DEFAULT NULL,
    hora_inicio TIME DEFAULT NULL,
    hora_fin TIME DEFAULT NULL,
    fecha_asignacion DATE DEFAULT NULL,
    PRIMARY KEY (id_entrenador, id_persona),
    KEY id_persona (id_persona),
    FOREIGN KEY (id_entrenador) REFERENCES PERSONA(id_persona),
    FOREIGN KEY (id_persona) REFERENCES PERSONA(id_persona)
);

